import {at,group,createGame,play} from './engine.js';
const board=(n,black=[],white=[])=>{const b=Array(n*n).fill(0);black.forEach(([x,y])=>b[at(x,y,n)]=1);white.forEach(([x,y])=>b[at(x,y,n)]=2);return b;};
const point=(x,y,n=5)=>at(x,y,n);
const P=(text,b,answers,explain,hint,extra={})=>({kind:'place',text,board:b,size:Math.sqrt(b.length),player:1,answers,explain,hint,...extra});
const S=(text,b,answers,explain,hint,extra={})=>({...P(text,b,answers,explain,hint,extra),kind:'select',...extra});
const M=(text,b,answers,explain,hint,extra={})=>({...S(text,b,answers,explain,hint,extra),kind:'multi',...extra});
const Q=(text,choices,answer,explain,b=null,extra={})=>({kind:'choice',text,choices,answer,explain,hint:'설명을 다시 읽고, 바둑판의 변화를 떠올려보세요.',board:b,size:b?Math.sqrt(b.length):5,...extra});
const blank=n=>board(n);
const capture=board(5,[[1,2],[2,1],[3,2]],[[2,2]]);
const save=board(5,[[2,2]],[[1,2],[2,1],[3,2]]);
const link=board(5,[[1,2],[3,2]],[[0,2],[1,1],[1,3]]);
const cut=board(5,[[1,2],[3,2]],[[2,1]]);
const ko=board(5,[[1,2],[2,1],[3,2]],[[2,2],[1,3],[3,3],[2,4]]);
const koAfter=play(createGame(5,ko),point(2,3)).state.board;
const corner=board(5,[[0,2],[1,2],[2,2],[2,1],[2,0]],[[4,4],[4,3],[3,4]]);
const eyes=Array(25).fill(1);eyes[6]=0;eyes[18]=0;
const seki=Array.from({length:25},(_,p)=>p%5<2||(p%5===2&&Math.floor(p/5)<2)?1:2);seki[6]=0;seki[18]=0;seki[12]=0;
const doubleAtari=board(5,[[0,2],[1,1],[3,1],[4,2]],[[1,2],[3,2]]);
const settled=Array.from({length:81},(_,p)=>p%9<4?1:2);[10,28,52,70].forEach(p=>settled[p]=0);
const opening=board(9,[[2,2],[5,4],[6,6]],[[6,2],[3,4],[2,6]]);
const endGap=board(5,[[0,2],[1,2],[2,2],[2,1]],[[4,4],[4,3],[3,4]]);
const free=(text,n=5,b=null,player=1)=>P(text,b??blank(n),(b??blank(n)).map((v,i)=>!v?i:-1).filter(i=>i>=0),'잘 두셨어요. 돌은 선이 만나는 빈 교차점에 놓아요.','비어 있는 선의 교차점을 골라보세요.',{player,free:true});
const rotate=(a,t)=>{const n=a.size;const map=p=>{let x=p%n,y=Math.floor(p/n);for(let k=0;k<t;k++)[x,y]=[n-1-y,x];return at(x,y,n);};const b=Array(n*n).fill(0);a.board.forEach((c,p)=>b[map(p)]=c);return {...a,board:b,answers:a.answers?.map(map),marks:a.marks?.map(map)};};
const capTask=()=>P('흑돌을 놓아 가운데 백돌을 잡아보세요.',capture,[17],'마지막 활로가 막혀 백돌이 잡혔어요. 이것을 따내기라고 해요.','백돌의 상하좌우에서 비어 있는 한 곳을 찾아보세요.');
const saveTask=()=>P('활로가 하나인 흑돌을 구해보세요.',save,[17],'새로 놓은 흑돌과 연결되어 활로가 늘어났어요.','검은 돌 옆의 마지막 빈자리에 이어 두어보세요.');
const connectTask=()=>P('위험한 왼쪽 흑돌을 오른쪽 친구와 연결해보세요.',link,[12],'두 흑돌이 연결되어 하나의 돌무리가 되었어요.','두 검은 돌 사이를 살펴보세요.');
const libTask=(b,p,text)=>M(text,b,[...group(b,p,Math.sqrt(b.length)).liberties],'모두 찾았어요. 연결된 돌무리가 함께 쓰는 빈자리는 한 번만 세어요.','상하좌우의 빈자리만 세고 대각선은 빼주세요.',{marks:[p]});
const review=()=>Q('틀린 수를 발견했을 때 가장 도움이 되는 방법은?', ['처음부터 전부 외우기','실수 직전으로 돌아가 다른 수 비교하기','다시는 두지 않기'],1,'한 장면만 다시 보아도 다음 판에서 다른 선택을 할 수 있어요.');

